#!/data/data/com.termux/files/usr/bin/bash
set -euo pipefail
repo=BBlueSkyy/peanuts-native
branch=fix/android12-vulkan-compat
command -v gh >/dev/null && command -v git >/dev/null || { echo 'Instale: pkg install gh git'; exit 1; }
gh auth status || { echo 'Execute gh auth login primeiro'; exit 1; }
gh auth setup-git
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
git clone --depth 1 --filter=blob:none --sparse --branch "$branch" "https://github.com/$repo.git" "$work/repo"
cd "$work/repo"
git sparse-checkout set dm/games/0100A250097F0000
dir=dm/games/0100A250097F0000
test -f "$dir/game.tsv"
grep -q v1703936 "$dir/game.tsv"
